function validate([nums]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => v < 0 || v > 100)) return 'Each value is between 0 and 100.';
  if (!nums.includes(0)) return 'nums must contain at least one 0.';
  return null;
}

