function countValidSelections(nums) {
  const total = nums.reduce((sum, value) => sum + value, 0);
  let leftSum = 0;
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === 0) {
      const rightSum = total - leftSum;
      if (leftSum === rightSum) {
        count += 2;
      } else if (Math.abs(leftSum - rightSum) === 1) {
        count += 1;
      }
    }
    leftSum += nums[i];
  }
  return count;
}

