function countValidSelections(nums) {
  // Run the process literally for every zero and both directions on a copy of the array.
  let valid = 0;
  for (let start = 0; start < nums.length; start++) {
    if (nums[start] !== 0) continue;
    for (const first of [-1, 1]) {
      const values = nums.slice();
      let curr = start, dir = first;
      while (curr >= 0 && curr < values.length) {
        if (values[curr] === 0) {
          curr += dir;
        } else {
          values[curr]--;
          dir = -dir;
          curr += dir;
        }
      }
      if (values.every(v => v === 0)) valid++;
    }
  }
  return valid;
}

