function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 100 - pick(3) : 1 + pick(8);
  const top = large ? 100 : 1 + pick(5);
  const zeroRate = rand() * 0.6;
  const nums = Array.from({ length: n }, () => (rand() < zeroRate ? 0 : pick(top + 1)));
  const zero = pick(n);
  nums[zero] = 0;
  // Often rebuild the right side of that zero so its total is within one of the left side's,
  // so that valid selections actually occur.
  if (rand() < 0.6 && zero < n - 1) {
    const left = nums.slice(0, zero).reduce((a, b) => a + b, 0);
    let goal = Math.min(Math.max(0, left + pick(3) - 1), (n - zero - 1) * top);
    for (let i = zero + 1; i < n; i++) nums[i] = 0;
    while (goal > 0) {
      const i = zero + 1 + pick(n - zero - 1);
      if (nums[i] < top) { nums[i]++; goal--; }
    }
  }
  return [nums];
}
